import { createRouter, Navigate } from '@tanstack/react-router'
import { routeTree } from '@/routeTree.gen'
import { ErrorScreen } from './ErrorScreen'

// The routes are the files in `routes/`; see `routes/__root.tsx` for the map of them.
// `routeTree.gen.ts` is generated by the TanStack Router plugin in `vite.config.ts` when the
// dev server, a build or the tests run. It is committed, because `tsc -b` runs before the
// build in CI and needs it.
//
// The defaults are exported apart from the router so a test can put them on a route tree of
// its own.
export const routerDefaults = {
  // Unknown URL → the landing screen instead of the router's bare default 404.
  defaultNotFoundComponent: () => <Navigate to="/" replace />,
  // Without this the router catches a crashing route at the root and shows its own English
  // "Something went wrong!" in place of the whole app. With it every route has a boundary of
  // its own, so a crash in a work page leaves the map and the session around it standing.
  defaultErrorComponent: ErrorScreen,
}

export const router = createRouter({ routeTree, ...routerDefaults })

// The one type annotation the router needs: it is what makes Link, useNavigate and the
// route hooks typed everywhere else.
declare module '@tanstack/react-router' {
  interface Register {
    router: typeof router
  }
}
